// Drafting of bug reports and feature requests.
//
// The wording of a report and the URL that carries it are kept out of the
// window component so both can be tested without rendering React. The
// markdown produced here mirrors .github/ISSUE_TEMPLATE/*.md, so a report
// typed by hand and a report generated by the app end up in the same shape.

export const REPO_OWNER = 'PolarAudio';
export const REPO_NAME = 'TrueLazer';
export const ISSUES_URL = `https://github.com/${REPO_OWNER}/${REPO_NAME}/issues/new`;
export const REPO_URL = `https://github.com/${REPO_OWNER}/${REPO_NAME}`;

// Browsers and GitHub both start to reject very long URLs, so a report has a
// budget. The log tail is the first thing dropped because it is by far the
// longest part and the least essential in a link - it is still available on
// the clipboard.
export const MAX_ISSUE_URL_LENGTH = 6000;

export const REPORT_AREAS = [
    'Show Editor',
    'Timeline Editor',
    'Shape Builder',
    'Output Settings',
    'DAC Communication',
    'MIDI / Keyboard Shortcuts',
    'ArtNet / DMX',
    'OSC',
    'Audio / FFT',
    'ILDA Export / Import',
    'DJ Link / ProLink / StageLinq',
    'Startup / Installation',
    'Other',
];

export const BUG_SEVERITIES = [
    { value: 'show-stopper', label: 'Show-stopper - the show cannot run' },
    { value: 'broken', label: 'Broken - a feature does not work' },
    { value: 'workaround', label: 'Workaround - I can get around it' },
    { value: 'cosmetic', label: 'Cosmetic - it looks or feels wrong' },
];

export const severityLabel = (value) =>
    (BUG_SEVERITIES.find((s) => s.value === value) || {}).label || '';

const section = (title, body) => {
    const text = (body ?? '').trim();
    if (!text) return '';
    return `## ${title}\n\n${text}\n\n`;
};

// Steps are typed one per line; the template wants them numbered, so they are
// renumbered here. A line that already looks like a number keeps its own
// text but still gets the correct index.
export const toNumberedList = (text = '') => {
    const lines = String(text)
        .split(/\r?\n/)
        .map(line => line.trim())
        .filter(line => line.length > 0);
    if (lines.length === 0) return '';
    return lines
        .map((line, index) => `${index + 1}. ${line.replace(/^\d+[.)]\s*/, '')}`)
        .join('\n');
};

// The environment block. `extra` carries the facts only the renderer knows:
// the GPU string, the page the user was on, and the DACs that were found.
export const formatEnvironment = (diagnostics = {}, extra = {}) => {
    const app = diagnostics.app || {};
    const system = diagnostics.system || {};
    const lines = [
        `- TrueLazer: ${app.version || 'unknown'}${app.packaged ? '' : ' (development build)'}`,
        `- Electron / Chromium / Node: ${app.electron || '?'} / ${app.chrome || '?'} / ${app.node || '?'}`,
        `- OS: ${system.osName || system.platform || '?'} ${system.osRelease || ''} (${system.platform || '?'} ${system.arch || ''})`.trim(),
        `- CPU: ${system.cpuModel || '?'} (${system.cpuCores || '?'} cores)`,
        `- Memory: ${system.totalMemoryMB ?? '?'} MB total, ${system.freeMemoryMB ?? '?'} MB free`,
    ];
    if (extra.gpu) lines.push(`- GPU: ${extra.gpu}`);
    if (extra.page) lines.push(`- Page: ${extra.page}`);
    if (extra.dac) lines.push(`- DAC: ${extra.dac}`);
    return lines.join('\n');
};

export const composeBugReport = (draft = {}, options = {}) => {
    const {
        title = '', severity = '', area = '',
        whatHappened = '', expected = '', steps = '',
    } = draft;
    let body = '';
    body += section('Summary', title);
    body += section('Severity', severityLabel(severity));
    body += section('Area', area);
    body += section('What happened', whatHappened);
    body += section('What I expected', expected);
    body += section('Steps to reproduce', toNumberedList(steps));
    if (options.environment) body += `## Environment\n\n${options.environment}\n\n`;
    if (options.logTail) body += `## Log tail\n\n\`\`\`\n${options.logTail}\n\`\`\`\n\n`;
    return body.trimEnd() + '\n';
};

export const composeFeatureReport = (draft = {}, options = {}) => {
    const {
        title = '', area = '', problem = '', proposal = '', why = '', alternatives = '',
    } = draft;
    let body = '';
    body += section('Summary', title);
    body += section('Area', area);
    body += section('The problem you are trying to solve', problem);
    body += section('Proposed solution', proposal);
    body += section('Why it matters', why);
    body += section('Alternatives you considered', alternatives);
    if (options.environment) body += `## Environment\n\n${options.environment}\n\n`;
    return body.trimEnd() + '\n';
};

export const buildIssueUrl = ({ title = '', body = '', label = '' } = {}) => {
    const params = new URLSearchParams();
    if (label) params.set('labels', label);
    if (title) params.set('title', title);
    if (body) params.set('body', body);
    return `${ISSUES_URL}?${params.toString()}`;
};

// Removes the log tail section from a composed body. The tail is always the
// last section, so everything from its heading onwards can go.
export const stripLogTail = (body = '') => {
    const marker = '\n## Log tail\n';
    const index = body.indexOf(marker);
    if (index === -1) return body;
    return body.slice(0, index).trimEnd() + '\n';
};

// Trims a body at a line boundary until the resulting URL fits the budget.
const buildFittingUrl = ({ title, body, label, maxLength }) => {
    const full = buildIssueUrl({ title, body, label });
    if (full.length <= maxLength) return { url: full, overBudget: false };
    const overhead = full.length - body.length;
    const budget = Math.max(0, maxLength - overhead);
    const trimmed = body.slice(0, budget);
    const lastBreak = trimmed.lastIndexOf('\n');
    const safe = lastBreak > 0 ? trimmed.slice(0, lastBreak) : trimmed;
    return { url: buildIssueUrl({ title, body: safe, label }), overBudget: true };
};

// Produces the link that opens a pre-filled GitHub issue. The log tail is
// dropped first when the report does not fit, and the user is told so they
// can paste the tail from the clipboard instead.
export const fitIssueUrl = ({ title = '', body = '', label = '' } = {}) => {
    const withoutLogs = stripLogTail(body);
    const hasLogs = withoutLogs !== body;
    const direct = buildIssueUrl({ title, body, label });
    if (direct.length <= MAX_ISSUE_URL_LENGTH) {
        return { url: direct, droppedLogTail: false, overBudget: false };
    }
    const fitted = buildFittingUrl({ title, body: withoutLogs, label, maxLength: MAX_ISSUE_URL_LENGTH });
    return { url: fitted.url, droppedLogTail: hasLogs, overBudget: fitted.overBudget };
};

// A one line summary of the DACs that were found. MAC addresses are
// deliberately left out - they identify the hardware and identify the owner.
export const formatDacSummary = (dacs = []) => {
    if (!Array.isArray(dacs) || dacs.length === 0) return '';
    return dacs
        .map((dac) => {
            if (!dac) return '';
            const kind = dac.type || 'DAC';
            const where = dac.ip || dac.name || '';
            return where ? `${kind} @ ${where}` : kind;
        })
        .filter(Boolean)
        .join(', ');
};
